-- 📚 꼭집 주거 사전 — 일반 매입임대 순위 구조(1순위 우선·1순위 일반·2순위 · 후순위 목록 따로 게시) · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값 「매입임대」.
-- 꼴 A = 정책 문장에 「1순위 (우선)」과 「1순위 (일반)」이 함께 · hu = 「후순위 공급대상주택 목록 … 게시」 · 자격 행 supply_form 이 「1순위(우선)」 꼴인지(ua_elig).
-- 🔵 2026-11-09(조사 「사전 5차 후보 둘」 1-ⓐ 초안 · 우편함 「코드·운영 — 📚 사전 SQL 새 둘 + 개정 둘 …」 1) — ua_elig 8 = 꼴 A 7 + 울산 …20334(꼴 D).
-- 확인 2026-11-09 · 실행 약 4초(관리 API 왕복) · 결과:
-- {"anns": 94, "ug": 7, "ug_hu": 7, "hu": 7, "ua_elig": 8, "ug_ex": ["2015122300020972", "2015122300020882", "2015122300020875", "2015122300020769"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.title,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t from announcement_policies p join a using(announcement_id) where a.yr=2026 and a.std='매입임대'),f as(select announcement_id,bool_or(t~'1순위\s*\(?\s*우선')u,bool_or(t~'1순위\s*\(?\s*일반')g,bool_or(t~'후순위\s*공급\s*대상\s*주택\s*목록')hu from y group by 1),e as(select distinct ec.announcement_id from eligibility_criteria ec join a on a.announcement_id=ec.announcement_id and a.yr=2026 and a.std='매입임대' where ec.supply_form~'^1순위\s*\(\s*우선')select json_build_object('anns',(select count(*) from f),'ug',(select count(*) from f where u and g),'ug_hu',(select count(*) from f where u and g and hu),'hu',(select count(*) from f where hu),'ua_elig',(select count(*) from e),'ug_ex',(select json_agg(i) from(select announcement_id i from f where u and g order by 1 desc limit 4)q))j;
